(function () {
  var script = document.currentScript;
  var data = (script && script.dataset) || {};

  var TEXTURE = 'data:image/png;base64,';

  var KEY = (data.key || 'p').toLowerCase();
  var W = parseFloat(data.width) || 160;
  var H = W * 3 / 4;
  var hw = W / 2, hh = H / 2;

  var GRAVITY = data.gravity !== undefined ? parseFloat(data.gravity) : 1400;
  var RESTITUTION = 0.9;
  var FRICTION = 0.15;
  var AIR_DRAG = 0.01;
  var SPIN_DRAG = 0.04;
  var REST_SPEED = 40;
  var SPRING_K = 220;
  var SPRING_C = 22;

  var mass = 1;
  var inertia = mass * (W * W + H * H) / 12;

  var style = document.createElement('style');
  style.textContent =
    '.pbox{position:fixed;left:0;top:0;width:' + W + 'px;height:' + H + 'px;' +
    'margin:' + (-hh) + 'px 0 0 ' + (-hw) + 'px;' +
    'background:url("' + TEXTURE + '") center/100% 100% no-repeat;' +
    'cursor:grab;touch-action:none;will-change:transform;z-index:2147483647;' +
    'user-select:none;-webkit-user-select:none;-webkit-user-drag:none}' +
    '.pbox.dragging{cursor:grabbing}';
  (document.head || document.documentElement).appendChild(style);

  var SOUNDS = [
    'data:audio/mpeg;base64,',
    'data:audio/mpeg;base64,'
  ];

  function playSound() {
    var pick = Math.floor(Math.random() * SOUNDS.length);
    var a = new Audio(SOUNDS[pick]);
    a.volume = 0.6;
    a.play().catch(function () {});
  }

  function scheduleSound(b) {
    b.timer = setTimeout(function () {
      if (!b.el.isConnected) return;
      playSound();
      scheduleSound(b);
    }, 1000 + Math.random() * 2000);
  }

  var bodies = [];
  var mouse = { x: innerWidth / 2, y: innerHeight / 2 };

  addEventListener('pointermove', function (e) {
    mouse.x = e.clientX;
    mouse.y = e.clientY;
  });

  addEventListener('keydown', function (e) {
    if (this.window.gameOpen) return;
    if (e.repeat || e.ctrlKey || e.metaKey || e.altKey) return;
    if (e.key.toLowerCase() !== KEY) return;
    var t = e.target;
    if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
    spawn(mouse.x, mouse.y);
  });

  function spawn(x, y) {
    var el = document.createElement('div');
    el.className = 'pbox';
    document.body.appendChild(el);

    var b = {
      el: el, x: x, y: y, a: 0, vx: 0, vy: 0, w: 0, grab: null, timer: null
    };
    bodies.push(b);
    playSound();
    scheduleSound(b);

    el.addEventListener('pointerdown', function (e) {
      e.preventDefault();
      el.setPointerCapture(e.pointerId);
      el.classList.add('dragging');
      var dx = e.clientX - b.x, dy = e.clientY - b.y;
      var c = Math.cos(-b.a), s = Math.sin(-b.a);
      b.grab = {
        lx: dx * c - dy * s,
        ly: dx * s + dy * c,
        cx: e.clientX, cy: e.clientY
      };
    });
    el.addEventListener('pointermove', function (e) {
      if (b.grab) { b.grab.cx = e.clientX; b.grab.cy = e.clientY; }
    });
    function release() { b.grab = null; el.classList.remove('dragging'); }
    el.addEventListener('pointerup', release);
    el.addEventListener('pointercancel', release);

    el.style.transform = 'translate(' + x + 'px,' + y + 'px)';
  }

  function corners(b) {
    var c = Math.cos(b.a), s = Math.sin(b.a);
    return [[-hw, -hh], [hw, -hh], [hw, hh], [-hw, hh]].map(function (p) {
      return { rx: p[0] * c - p[1] * s, ry: p[0] * s + p[1] * c };
    });
  }

  var walls = [
    { nx: 1,  ny: 0,  d: function (p) { return p.x; } },
    { nx: -1, ny: 0,  d: function (p) { return innerWidth - p.x; } },
    { nx: 0,  ny: 1,  d: function (p) { return p.y; } },
    { nx: 0,  ny: -1, d: function (p) { return innerHeight - p.y; } }
  ];

  function collideWalls(b) {
    for (var iter = 0; iter < 3; iter++) {
      for (var wi = 0; wi < walls.length; wi++) {
        var wall = walls[wi];
        var cs = corners(b);
        for (var ci = 0; ci < cs.length; ci++) {
          var k = cs[ci];
          var dist = wall.d({ x: b.x + k.rx, y: b.y + k.ry });
          if (dist >= 0) continue;
          b.x += wall.nx * -dist;
          b.y += wall.ny * -dist;
          var vx = b.vx - b.w * k.ry;
          var vy = b.vy + b.w * k.rx;
          var vn = vx * wall.nx + vy * wall.ny;
          if (vn >= 0) continue;
          var rn = k.rx * wall.ny - k.ry * wall.nx;
          var invN = 1 / mass + rn * rn / inertia;
          var e = -vn < REST_SPEED ? 0 : RESTITUTION;
          var j = -(1 + e) * vn / invN;
          b.vx += wall.nx * j / mass;
          b.vy += wall.ny * j / mass;
          b.w += rn * j / inertia;
          var tx = -wall.ny, ty = wall.nx;
          var vt = vx * tx + vy * ty;
          var rt = k.rx * ty - k.ry * tx;
          var invT = 1 / mass + rt * rt / inertia;
          var jt = -vt / invT;
          jt = Math.max(-FRICTION * j, Math.min(FRICTION * j, jt));
          b.vx += tx * jt / mass;
          b.vy += ty * jt / mass;
          b.w += rt * jt / inertia;
        }
      }
    }
  }

  function inBox(b, px, py, eps) {
    var dx = px - b.x, dy = py - b.y;
    var c = Math.cos(-b.a), s = Math.sin(-b.a);
    var lx = dx * c - dy * s, ly = dx * s + dy * c;
    return Math.abs(lx) <= hw + eps && Math.abs(ly) <= hh + eps;
  }

  function collidePair(A, B) {
    var dx = B.x - A.x, dy = B.y - A.y;
    var maxR = Math.sqrt(W * W + H * H);
    if (dx * dx + dy * dy > maxR * maxR) return;

    var axes = [];
    [A, B].forEach(function (o) {
      var c = Math.cos(o.a), s = Math.sin(o.a);
      axes.push([c, s], [-s, c]);
    });

    var minOv = Infinity, nx = 0, ny = 0;
    for (var i = 0; i < axes.length; i++) {
      var ax = axes[i][0], ay = axes[i][1];
      var cA = Math.cos(A.a), sA = Math.sin(A.a);
      var cB = Math.cos(B.a), sB = Math.sin(B.a);
      var hA = hw * Math.abs(ax * cA + ay * sA) + hh * Math.abs(-ax * sA + ay * cA);
      var hB = hw * Math.abs(ax * cB + ay * sB) + hh * Math.abs(-ax * sB + ay * cB);
      var dist = dx * ax + dy * ay;
      var ov = hA + hB - Math.abs(dist);
      if (ov <= 0) return;
      if (ov < minOv) {
        minOv = ov;
        var sign = dist >= 0 ? 1 : -1;
        nx = ax * sign;
        ny = ay * sign;
      }
    }

    var px = 0, py = 0, cnt = 0;
    [[A, B], [B, A]].forEach(function (pair) {
      var src = pair[0], dst = pair[1];
      var c = Math.cos(src.a), s = Math.sin(src.a);
      [[-hw, -hh], [hw, -hh], [hw, hh], [-hw, hh]].forEach(function (p) {
        var wx = src.x + p[0] * c - p[1] * s;
        var wy = src.y + p[0] * s + p[1] * c;
        if (inBox(dst, wx, wy, 1)) { px += wx; py += wy; cnt++; }
      });
    });
    if (cnt === 0) { px = (A.x + B.x) / 2; py = (A.y + B.y) / 2; }
    else { px /= cnt; py /= cnt; }

    var push = minOv / 2;
    A.x -= nx * push; A.y -= ny * push;
    B.x += nx * push; B.y += ny * push;

    var rAx = px - A.x, rAy = py - A.y;
    var rBx = px - B.x, rBy = py - B.y;
    var vAx = A.vx - A.w * rAy, vAy = A.vy + A.w * rAx;
    var vBx = B.vx - B.w * rBy, vBy = B.vy + B.w * rBx;
    var rvx = vBx - vAx, rvy = vBy - vAy;
    var vn = rvx * nx + rvy * ny;
    if (vn >= 0) return;

    var rAn = rAx * ny - rAy * nx;
    var rBn = rBx * ny - rBy * nx;
    var invN = 2 / mass + rAn * rAn / inertia + rBn * rBn / inertia;
    var e = -vn < REST_SPEED ? 0 : RESTITUTION;
    var j = -(1 + e) * vn / invN;
    A.vx -= nx * j / mass; A.vy -= ny * j / mass; A.w -= rAn * j / inertia;
    B.vx += nx * j / mass; B.vy += ny * j / mass; B.w += rBn * j / inertia;

    var tx = -ny, ty = nx;
    var vt = rvx * tx + rvy * ty;
    var rAt = rAx * ty - rAy * tx;
    var rBt = rBx * ty - rBy * tx;
    var invT = 2 / mass + rAt * rAt / inertia + rBt * rBt / inertia;
    var jt = -vt / invT;
    jt = Math.max(-FRICTION * j, Math.min(FRICTION * j, jt));
    A.vx -= tx * jt / mass; A.vy -= ty * jt / mass; A.w -= rAt * jt / inertia;
    B.vx += tx * jt / mass; B.vy += ty * jt / mass; B.w += rBt * jt / inertia;
  }

  function step(b, dt) {
    var fx = 0, fy = GRAVITY * mass, torque = 0;

    if (b.grab) {
      var g = b.grab;
      var c = Math.cos(b.a), s = Math.sin(b.a);
      var rx = g.lx * c - g.ly * s;
      var ry = g.lx * s + g.ly * c;
      var vx = b.vx - b.w * ry;
      var vy = b.vy + b.w * rx;
      var sx = SPRING_K * (g.cx - (b.x + rx)) - SPRING_C * vx;
      var sy = SPRING_K * (g.cy - (b.y + ry)) - SPRING_C * vy;
      fx += sx;
      fy += sy;
      torque += rx * sy - ry * sx;
      b.w *= 1 - Math.min(1, 3 * dt);
    }

    b.vx += fx / mass * dt;
    b.vy += fy / mass * dt;
    b.w += torque / inertia * dt;

    b.vx *= 1 - AIR_DRAG * dt;
    b.vy *= 1 - AIR_DRAG * dt;
    b.w *= 1 - SPIN_DRAG * dt;

    b.x += b.vx * dt;
    b.y += b.vy * dt;
    b.a += b.w * dt;

    collideWalls(b);
  }

  var last = performance.now();
  function frame(now) {
    var frameDt = Math.min((now - last) / 1000, 0.05);
    last = now;
    var SUB = 6;
    for (var i = 0; i < SUB; i++) {
      for (var n = 0; n < bodies.length; n++) step(bodies[n], frameDt / SUB);
      for (var p = 0; p < 2; p++) {
        for (var m = 0; m < bodies.length; m++) {
          for (var o = m + 1; o < bodies.length; o++) collidePair(bodies[m], bodies[o]);
        }
        for (var q = 0; q < bodies.length; q++) collideWalls(bodies[q]);
      }
    }
    for (var n2 = 0; n2 < bodies.length; n2++) {
      var b = bodies[n2];
      b.el.style.transform =
        'translate(' + b.x + 'px,' + b.y + 'px) rotate(' + b.a + 'rad)';
    }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();